// Package postgres keeps the DPoP proofs garam accepted and the nonces
// it issued in PostgreSQL via jackc/pgx (ADR-0191 decisions 4 and 5),
// so every replica refuses a replay and accepts any replica's nonce.
// The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/platform/internal/dpop"
	"github.com/garamsh/garam/platform/internal/dpop/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
)

// Store satisfies [dpop.Store].
type Store struct {
	q *db.Queries
}

var _ dpop.Store = (*Store)(nil)

// New returns a Store over pool.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

func interval(d time.Duration) pgtype.Interval {
	return pgtype.Interval{Microseconds: d.Microseconds(), Valid: true}
}

// SpendJTI sweeps every expired jti, then records jti for jkt unless a
// row already holds it. The primary key decides between two replicas
// spending the same jti at once.
func (s *Store) SpendJTI(ctx context.Context, jkt, jti string, ttl time.Duration) (bool, error) {
	if err := s.q.SweepJTIs(ctx); err != nil {
		return false, pgxerr.Classify(err, "sweep dpop jtis", nil, nil)
	}
	_, err := s.q.SpendJTI(ctx, db.SpendJTIParams{Jkt: jkt, Jti: jti, Ttl: interval(ttl)})
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, pgxerr.Classify(err, "spend dpop jti", nil, nil)
	}
	return true, nil
}

// IssueNonce sweeps every expired nonce, then records nonce.
func (s *Store) IssueNonce(ctx context.Context, nonce string, ttl time.Duration) error {
	if err := s.q.SweepNonces(ctx); err != nil {
		return pgxerr.Classify(err, "sweep dpop nonces", nil, nil)
	}
	if err := s.q.IssueNonce(ctx, db.IssueNonceParams{Nonce: nonce, Ttl: interval(ttl)}); err != nil {
		return pgxerr.Classify(err, "issue dpop nonce", nil, nil)
	}
	return nil
}

// NonceLive answers whether a row holds nonce and has not expired.
func (s *Store) NonceLive(ctx context.Context, nonce string) (bool, error) {
	live, err := s.q.NonceLive(ctx, nonce)
	if err != nil {
		return false, pgxerr.Classify(err, "read dpop nonce", nil, nil)
	}
	return live, nil
}
